const frameOf = (src) => { const m = src.match(/%2F([^?]+?)\.jpe?g/i); return m ? decodeURIComponent(m[1]) : undefined; };

/* ---------------------------------------------------------------- */
/* One-off pieces for this article only                             */
/* ---------------------------------------------------------------- */

/*
 * Every scan is exactly 3000x2062 (landscape) or 2062x3000 (portrait).
 * All tiles render the FULL frame at its native aspect — no cropping.
 * Collage columns are sized in fr units proportional to aspect ratio so
 * rows stay flush without cutting into any photo.
 */
function Photo({ src, alt, className = '', priority = false, eager = false, sizes = '100vw' }) {
    const blur = BLUR[frameOf(src)];
    return (
        <div className={`relative overflow-hidden ${className}`}>
            <Image
                src={src}
                alt={alt}
                fill
                priority={priority}
                loading={eager && !priority ? 'eager' : undefined}
                sizes={sizes}
                placeholder={blur ? 'blur' : 'empty'}
                blurDataURL={blur}
                className="object-cover"
            />
        </div>
    );
}

function Land({ src, alt, sizes = '33vw', priority = false, eager = false, className = '' }) {
    return <Photo src={src} alt={alt} className={`aspect-[3000/2062] w-full ${className}`} sizes={sizes} priority={priority} eager={eager} />;
}

function Port({ src, alt, sizes = '25vw', eager = false, className = '' }) {
    return <Photo src={src} alt={alt} className={`aspect-[2062/3000] w-full ${className}`} sizes={sizes} eager={eager} />;
}

function Chip({ children }) {
    return (
        <span className={`${heading.className} text-white text-lg px-5 py-0.5 uppercase tracking-[0.12em]`} style={{ backgroundColor: GREEN }}>
            {children}
        </span>
    );
}

function PlaceCard({ name, children }) {
    return (
        <div>
            <Chip>{name}</Chip>
            <p className={`${body.className} text-gray-800 text-base mt-2 leading-normal`}>{children}</p>
        </div>
    );
}

/* Route collage — castles and night rail left, map + floating torii center, shrines rail right.
   Each rail holds full frames; leftover rail space stays black like the mockup. */
function RouteSection() {
    return (
        <section className="bg-black grid grid-cols-1 sm:grid-cols-[1fr_3.4fr_1fr] gap-2 p-2">
            <div className="grid grid-cols-2 gap-2 items-start sm:flex sm:flex-col sm:justify-between">
                <Port src={kokuraCastle} alt="Kokura Castle above stone walls and trees" sizes="20vw" />
                <Port src={hiroshimaCastle} alt="Hiroshima Castle keep" sizes="20vw" />
                <Land src={toriiGate} alt="Torii gate at the entrance of Fushimi Inari" sizes="20vw" />
                <Land src={duskBay} alt="Pink dusk over the bay islands" sizes="20vw" />
            </div>
            <div className="flex flex-col gap-2 order-first sm:order-none">
                <div className="bg-[#f2ead9] flex items-center justify-center p-6 sm:p-10">
                    <div className="relative w-full aspect-[863/593]">
                        <Image src={routeMap} alt="Map of Japan with the route from Tokyo to Nagasaki" fill sizes="60vw" className="object-contain" />
                    </div>
                </div>
                <Land src={floatingToriiWide} alt="The floating torii of Miyajima at low tide" sizes="60vw" />
            </div>
            <div className="grid grid-cols-2 gap-2 items-start sm:flex sm:flex-col sm:justify-between">
                <Port src={cbdNeon} alt="Neon signs over a late-night food stall" sizes="20vw" className="order-1" />
                <Land src={forestPagoda} alt="Pagoda rising out of a misty forest" sizes="20vw" className="order-3 sm:order-2" />
                <Land src={toriiTunnel} alt="Tunnel of orange torii gates" sizes="20vw" className="order-4 sm:order-3" />
                <Port src={nagasakiOverlook} alt="Overlook road above the city of Nagasaki" sizes="20vw" className="order-2 sm:order-4" />
            </div>
        </section>
    );
}

function CitiesSection() {
    return (
        <section className="grid grid-cols-1 sm:grid-cols-[1fr_1.6fr] gap-4 w-full">
            <div className="grid gap-4 content-start">
                <Port src={monkeyFence} alt="Monkey inspecting a watch through the fence on Miyajima" sizes="40vw" />
                <Port src={floatingToriiTall} alt="The floating torii gate of Itsukushima Shrine" sizes="40vw" />
            </div>
            <div className="grid sm:grid-cols-2 gap-x-12 gap-y-8 content-evenly p-4 sm:py-4 sm:pr-12">
                <PlaceCard name="Tokyo">
                    Tokyo was everything that I expected. Small side streets. Amazing food. The culture shock
                    was interesting. I&apos;ve never been surrounded by so many people, but felt completely alone.
                    I walked 20+ miles a day soaking it all in.
                </PlaceCard>
                <PlaceCard name="Yokohama">
                    I was here as a day trip out of Tokyo. I met some Americans and went to a bar with tons of
                    vinyl. Hearing Willie Nelson at a bar in Japan is a fun experience.
                </PlaceCard>
                <PlaceCard name="Mt. Fuji">
                    Beautiful. Slow. I saw a family at a bonfire as I was walking to get ramen that made my
                    heart happy. Mt. Fuji made my heart happy. The slowness was much needed after a few days
                    in Tokyo.
                </PlaceCard>
                <PlaceCard name="Nagoya">
                    The &quot;dirtiest&quot; city I went to, but it would be the cleanest city in America. I went to the
                    bars with a few Americans that I met. Interesting to say the least...
                </PlaceCard>
                <PlaceCard name="Osaka">
                    Huge. Osaka, Kyoto, and Nara all run together in my mind. I liked the bay, the food. I went
                    to a bakery I saw on Instagram 5 years prior. It was worth the wait.
                </PlaceCard>
                <PlaceCard name="Kyoto">
                    I need a redo. I had a blast walking around, but where is the &quot;Old City&quot;? I was hoping to
                    see some more old stuff you know?
                </PlaceCard>
                <PlaceCard name="Nara">
                    DEER!! That is all. Some tourists as well. Too many tourists in fact. Great little
                    &quot;hikes&quot; and some amazing food!
                </PlaceCard>
                <PlaceCard name="Kitakyushu">
                    My ferry landed here. It was a fun ride, but I am glad that I only stayed a day or so. I
                    went to a church that had a goofy pastor that was helped by 3 little girls. Very funny.
                    Maybe even more so because I couldn&apos;t understand anything.
                </PlaceCard>
            </div>
        </section>
    );
}

